import java.util.*;
import java.util.concurrent.*;

public class MultiAgentSystem implements Runnable{
     private List<Thread> agents;

     public void addAgent(Thread agent) { agents.add(agent); }

     public void runAgents() throws InterruptedException{
         for(Thread agent : agents){
             agent.start();
         }   
         for(Thread agent : agents){
             agent.join();
         }   
     } 

     @Override public void run(){
          // 실행 로직 구현 
     }   
}
